insert into public.maintenance_programs (name, procedure_text, procedure_sha256, interval_months, periodicity_basis, requires_review) values ('Programa preventivo - Luminometro', 'Limpieza de superficies externas: Limpie y desinfecte la carcasa exterior del equipo al menos una vez al día. Apagado y desconexión previa: Apague siempre el luminómetro y desconecte el cable de alimentación o el cable USB antes de realizar cualquier tarea de limpieza externa. Cuidado de la batería: El equipo utiliza una batería de ion-litio recargable que ofrece aproximadamente 8 horas de uso continuo. Cuidado de la cámara de medición.', '7092b470fcb45f08b9df3ac4d2e77f33beec6c7eb51a4efe53a24b898d16f5b2', null, 'Pendiente de definir según fabricante y evaluación de riesgo', true) on conflict (procedure_sha256) do nothing;
