insert into public.maintenance_programs (name, procedure_text, procedure_sha256, interval_months, periodicity_basis, requires_review) values ('Programa preventivo - Resonancia magnetica', 'VERIFICACIÓN DIARIA: Revisar el funcionamiento de la caja de alarmas, indicadores y señales de advertencia. Comprobar que el piso de la sala esté limpio y libre de líquidos, que no existan objetos o materiales ferromagnéticos dentro de la sala de exploración y que las salidas de ventilación estén despejadas.
insert into public.maintenance_programs (name, procedure_text, procedure_sha256, interval_months, periodicity_basis, requires_review) values ('Programa preventivo - Sala de hemodinamia', 'INSPECCIÓN VISUAL: Revisar el estado general del equipo, cubiertas, estructura, brazo en C, mesa del paciente y soportes. Verificar que no existan daños, piezas flojas u obstrucciones.
insert into public.maintenance_programs (name, procedure_text, procedure_sha256, interval_months, periodicity_basis, requires_review) values ('Programa preventivo - Sierra para yeso', 'INSPECCIÓN VISUAL: Revisar antes de cada uso el estado general del equipo y sus accesorios. Verificar que el cable de alimentación no presente desgaste, abrasiones o daños.
